@page "/dispatch"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatch Dashboard</PageTitle>

<h1>🚚 Dispatch Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <label class="form-label">Filter by Status</label>
        <select class="form-select" @bind="selectedStatusFilter">
            <option value="">All</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-4">
        <label class="form-label">Search Destination</label>
        <input type="text" class="form-control" placeholder="Search..." @bind="destinationSearch" @bind:event="oninput" />
    </div>
    <div class="col-md-4 d-flex align-items-end">
        <button class="btn btn-outline-secondary" @onclick="LoadShipments">
            🔄 Refresh
        </button>
    </div>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Customer</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>@shipment.CustomerEmail</td>
                        <td>
                            <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                    value="@shipment.Status"
                                    @onchange="(e) => UpdateStatus(shipment, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status" selected="@(status == shipment.Status)">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<Shipment>? shipments;
    private string selectedStatusFilter = "";
    private string destinationSearch = "";

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private IEnumerable<Shipment> FilteredShipments
    {
        get
        {
            if (shipments is null) return [];
            var result = shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(selectedStatusFilter) && Enum.TryParse<ShipmentStatus>(selectedStatusFilter, out var status))
            {
                result = result.Where(s => s.Status == status);
            }

            if (!string.IsNullOrWhiteSpace(destinationSearch))
            {
                result = result.Where(s => s.Destination.Contains(destinationSearch, StringComparison.OrdinalIgnoreCase));
            }

            return result;
        }
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            if (updated is not null)
            {
                shipment.Status = updated.Status;
            }
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/my-shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>My Shipments</PageTitle>

<h1>📦 My Shipments</h1>

@if (shipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!shipments.Any())
{
    <div class="alert alert-info">
        <p>You don't have any shipments yet.</p>
    </div>
}
else
{
    <div class="row">
        @foreach (var shipment in shipments)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100 @GetCardBorderClass(shipment.Status)">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <code>@shipment.TrackingNumber</code>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="card-text"><strong>@shipment.Description</strong></p>
                        <p class="card-text">
                            <small class="text-muted">From:</small> @shipment.Origin<br />
                            <small class="text-muted">To:</small> @shipment.Destination
                        </p>
                        <hr />
                        <p class="card-text">
                            <span class="bi bi-calendar"></span>
                            <strong>Estimated Delivery:</strong><br />
                            <span class="fs-5">@shipment.EstimatedDelivery.ToString("dddd, MMM dd, yyyy")</span>
                        </p>
                        @if (shipment.Status == ShipmentStatus.Delivered)
                        {
                            <div class="alert alert-success mb-0 mt-2 p-2">
                                ✅ Delivered!
                            </div>
                        }
                        else if (shipment.Status == ShipmentStatus.Delayed)
                        {
                            <div class="alert alert-danger mb-0 mt-2 p-2">
                                ⚠️ This shipment has been delayed. Updated ETA will be provided soon.
                            </div>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

